class Solution {
public:
    int thirdMax(vector<int>& nums) {
        set<int> topSet;
        for (int num : nums) {
            topSet.insert(num);
            if (topSet.size() > 3) {
                topSet.erase(topSet.begin()); // Remove the smallest of the top elements
            }
        }

        // If we have 3 or more distinct numbers, the third max is the smallest in our set
        if (topSet.size() == 3) {
            return *topSet.begin();
        }

        // Otherwise, return the maximum element in the set
        return *topSet.rbegin();
    }
};
